<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/config/config.php'; require_once ROOT_PATH.'/includes/session.php'; require_once ROOT_PATH.'/includes/functions.php'; require_once ROOT_PATH.'/middleware/business.php'; require_once ROOT_PATH.'/middleware/csrf.php';
$uid=(int)currentUserId();$nid=(int)($_GET['id']??0);$notice=null;$error=null;$neg=null;$messages=[];$negotiations=[];$db=null;
try{$db=Database::getInstance()->getConnection();if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken();$nid=(int)($_POST['negotiation_id']??$nid);if(isset($_POST['message'])){(new Negotiation())->addMessage($nid,$uid,(string)$_POST['message']);$notice='Message sent.';}elseif(isset($_POST['status'])){(new Negotiation())->updateStatus($nid,$uid,(string)$_POST['status']);$notice='Negotiation status updated.';}$neg=(new Negotiation())->find($nid,$uid);if($neg){$s=$db->prepare('SELECT m.*,u.first_name,u.last_name FROM negotiation_messages m JOIN users u ON u.id=m.user_id WHERE m.negotiation_id=? ORDER BY m.created_at ASC');$s->execute([$nid]);$messages=$s->fetchAll();}}else{if(!$nid&&isset($_GET['quotation_id'])){$s=$db->prepare('SELECT n.id FROM negotiations n JOIN quotation_requests q ON q.id=n.quotation_request_id WHERE q.id=? AND q.buyer_id=? ORDER BY n.id DESC LIMIT 1');$s->execute([(int)$_GET['quotation_id'],$uid]);$nid=(int)$s->fetchColumn();}$neg=$nid?(new Negotiation())->find($nid,$uid):null;if($neg){$s=$db->prepare('SELECT m.*,u.first_name,u.last_name FROM negotiation_messages m JOIN users u ON u.id=m.user_id WHERE m.negotiation_id=? ORDER BY m.created_at ASC');$s->execute([$nid]);$messages=$s->fetchAll();}else{$s=$db->prepare('SELECT n.id,n.status,n.created_at,q.id AS quotation_id,COALESCE(GROUP_CONCAT(p.name SEPARATOR ", "),"Custom request") AS items,s.supplier_name FROM negotiations n JOIN quotation_requests q ON q.id=n.quotation_request_id LEFT JOIN quotation_items qi ON qi.quotation_request_id=q.id LEFT JOIN products p ON p.id=qi.product_id LEFT JOIN suppliers s ON s.id=q.supplier_id WHERE q.buyer_id=? GROUP BY n.id ORDER BY n.created_at DESC');$s->execute([$uid]);$negotiations=$s->fetchAll();}}}catch(Throwable $e){error_log('B2B negotiation: '.$e->getMessage());$error='Negotiation data is temporarily unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Negotiations - <?=e(SITE_NAME)?></title><link rel="stylesheet" href="<?=e(BASE_URL)?>/assets/css/style.css"></head><body class="b2b-page"><header class="directory-header"><div class="container directory-header-row"><a class="brand" href="<?=e(BASE_URL)?>/b2b/"><span class="brand-mark">Q</span><span><strong>QUINCY</strong><small>BUSINESS</small></span></a><nav><a href="<?=e(BASE_URL)?>/b2b/marketplace.php">Marketplace</a><a href="<?=e(BASE_URL)?>/b2b/suppliers.php">Suppliers</a><a href="<?=e(BASE_URL)?>/b2b/quotations.php">My RFQs</a><a class="directory-active" href="<?=e(BASE_URL)?>/b2b/negotiations.php">Negotiations</a></nav></div></header><main class="container b2b-main"><div class="directory-breadcrumb"><a href="<?=e(BASE_URL)?>/b2b/quotations.php">My RFQs</a><span>/</span>Negotiation</div><section class="rfq-heading"><p class="eyebrow">DIRECT SUPPLIER MESSAGING</p><h1><?= $neg?'Refine the offer together.':'Your negotiation room' ?></h1><p>Discuss pricing, delivery, packaging, and terms with a supplier.</p></section><?php if($notice):?><div class="catalog-notice"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="catalog-notice"><?=e($error)?></div><?php elseif(!$neg):?><?php if(!$negotiations):?><div class="supplier-empty"><h2>No negotiations yet</h2><p>Open a negotiation from one of your RFQs.</p><a href="<?=e(BASE_URL)?>/b2b/quotations.php">View my RFQs</a></div><?php else:?><div class="b2b-table"><?php foreach($negotiations as $n):?><div class="b2b-table-row"><div><strong><?=e($n['items'])?></strong><small><?=e($n['supplier_name']?:'Supplier')?></small></div><span class="status-badge status-<?=e($n['status'])?>"><?=e(ucfirst($n['status']))?></span><a href="<?=e(BASE_URL)?>/b2b/negotiations.php?id=<?= (int)$n['id']?>">Open conversation →</a></div><?php endforeach;?></div><?php endif;?><?php else:?><section class="communication-strip"><div><p class="eyebrow">RFQ #<?= (int)$neg['quotation_request_id']?></p><h2>Negotiation status: <span class="status-badge status-<?=e($neg['status'])?>"><?=e(ucfirst($neg['status']))?></span></h2></div><form method="post"><?=csrfField()?><input type="hidden" name="negotiation_id" value="<?= $nid?>"><select name="status"><option value="open">Open</option><option value="accepted">Accept terms</option><option value="rejected">Reject</option><option value="closed">Close</option></select><button class="outline-button">Update</button></form></section><section class="b2b-message-panel"><div class="b2b-messages"><?php if(!$messages):?><p class="supplier-empty">No messages yet. Start the conversation.</p><?php else:foreach($messages as $m):?><div class="b2b-message"><strong><?=e(trim($m['first_name'].' '.$m['last_name']))?></strong><small><?=e(date('M j, Y g:i A',strtotime((string)$m['created_at'])))?></small><p><?=nl2br(e($m['message']))?></p></div><?php endforeach;endif;?></div><form class="rfq-form" method="post"><?=csrfField()?><input type="hidden" name="negotiation_id" value="<?= $nid?>"><label>Write a message<textarea name="message" rows="4" required placeholder="Share your target terms or question"></textarea></label><button class="button button-primary">Send message →</button></form></section><?php endif;?></main></body></html>